input.content:
:root { --line:#e2e2e6; --muted:#6b7280; --accent:#2563eb; --bg:#f7f7f8; }
* { box-sizing:border-box; }
body { font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif; margin:0; background:var(--bg); color:#111; }
header { background:#fff; border-bottom:1px solid var(--line); padding:16px 28px; }
header h1 { font-size:18px; margin:0; }

.layout { max-width:920px; margin:0 auto; padding:24px; display:grid; grid-template-columns:190px 1fr; gap:24px; }
@media (max-width:640px){ .layout { grid-template-columns:1fr; } }

.side { display:flex; flex-direction:column; gap:4px; align-content:start; }
.side .lbl { font-size:11px; text-transform:uppercase; letter-spacing:.04em; color:var(--muted); margin:4px 12px 6px; }
.side button { text-align:left; background:none; border:none; padding:9px 12px; border-radius:8px; font-size:14px; cursor:pointer; color:#374151; }
.side button.active { background:#fff; border:1px solid var(--line); font-weight:600; }
.side button:hover { background:#eee; }

.saver { background:#fff; border:1px solid var(--line); border-radius:12px; padding:16px; }
.saver .row { display:flex; gap:10px; }
.saver input.url { flex:1; padding:10px 12px; border:1px solid var(--line); border-radius:8px; font-size:15px; }
.saver button.save { padding:10px 18px; border:none; background:var(--accent); color:#fff; font-size:15px; border-radius:8px; cursor:pointer; }
.saver button.save:hover { background:#1d4ed8; }

.chipbox { display:flex; flex-wrap:wrap; align-items:center; gap:6px; margin-top:10px; border:1px solid var(--line); border-radius:8px; padding:7px 9px; }
.chip { display:inline-flex; align-items:center; gap:6px; font-size:12px; color:#3730a3; background:#eef2ff; padding:3px 6px 3px 10px; border-radius:20px; }
.chip b { cursor:pointer; color:#6366f1; font-weight:700; }
.chipbox input { border:none; outline:none; font-size:14px; padding:4px; flex:1; min-width:120px; background:transparent; }
.hint { color:var(--muted); font-size:12px; margin:6px 2px 0; }

.savemsg { font-size:13px; margin:9px 2px 0; display:none; }
.savemsg.error { display:block; color:#b91c1c; }
.savemsg.warn { display:block; color:#92660b; }

.searchbar { margin-top:18px; }
.searchbar input { width:100%; padding:11px 14px; border:1px solid var(--line); border-radius:10px; font-size:15px; background:#fff; }

.count { color:var(--muted); font-size:13px; margin:14px 2px 10px; }
.noresult { color:var(--muted); text-align:center; padding:36px 0; font-size:15px; }

ul.list { list-style:none; padding:0; margin:0; display:flex; flex-direction:column; gap:10px; }
li.card { background:#fff; border:1px solid var(--line); border-radius:12px; padding:13px 15px; }
li.card.flash { animation:flash 1.2s ease; }
@keyframes flash { 0%{ background:#fff9db; } 100%{ background:#fff; } }
li.card .title { font-size:15px; font-weight:600; color:#111; text-decoration:none;
                 display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden; overflow-wrap:anywhere; }
li.card .title:hover { color:var(--accent); text-decoration:underline; }
li.card .url { display:block; color:var(--muted); font-size:13px; margin-top:3px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
li.card .tags { margin-top:9px; display:flex; flex-wrap:wrap; gap:6px; align-items:center; }
li.card .tag { font-size:12px; color:#3730a3; background:#eef2ff; padding:2px 10px; border-radius:20px; }

li.card .actions { margin-top:11px; display:flex; gap:14px; }
li.card .actions button { background:none; border:none; padding:0; font-size:12px; color:var(--muted); cursor:pointer; }
li.card .actions button:hover { color:#111; text-decoration:underline; }
li.card .actions button.danger:hover { color:#dc2626; }

.editor { margin-top:10px; border-top:1px dashed var(--line); padding-top:11px; }
.editor .chipbox2 { display:flex; flex-wrap:wrap; align-items:center; gap:6px; border:1px solid var(--line); border-radius:8px; padding:6px 8px; }
.editor .chip b { cursor:pointer; }
.editor .chipbox2 input { border:none; outline:none; font-size:14px; padding:4px; flex:1; min-width:120px; background:transparent; }
.editor .done { margin-top:9px; font-size:13px; background:var(--accent); color:#fff; border:none; padding:7px 14px; border-radius:8px; cursor:pointer; }

